def normalize_species(species: str | int | None) -> str:
    """Normalize species ID, hex string, or species name to 'cat', 'llama', or 'cloud'."""
    if species is None:
        return "cloud"
    if isinstance(species, int):
        if species == 0x0002:
            return "cat"
        if species == 0x0003:
            return "llama"
        if species == 0x0004:
            return "cloud"
        return "unknown"

    s = str(species).strip().lower()

    # Check for hex id patterns like "0x0002" or "0x0003 (Pwn Llama)"
    m = re.search(r"0x([0-9a-f]{4})", s)
    if m:
        val = int(m.group(1), 16)
        return normalize_species(val)

    if "llama" in s:
        return "llama"
    if "cat" in s or "gato" in s:
        return "cat"
    if "cloud" in s or "nube" in s:
        return "cloud"

    return "unknown"



